insert into public.site_settings (id, logo_url, favicon_url, colors, hero, seo, contact, social, sections, nav)
insert into public.content (key, value_ar, value_en) values
  ('brand.tagline', 'العماد لخدمات السيارات', 'AUTOMOTIVE SERVICES'),
  ('nav.cta', 'احجز موعدًا', 'Book an Appointment'),
  ('hero.eyebrow', 'JAPANESE AUTOMOTIVE SPECIALISTS', 'JAPANESE AUTOMOTIVE SPECIALISTS'),
  ('hero.title_1', 'YOUR CAR', 'YOUR CAR'),
  ('hero.title_2', 'DESERVES', 'DESERVES'),
  ('hero.title_accent', 'THE BEST', 'THE BEST'),
  ('hero.subtitle', 'العناية المثالية لسيارتك اليابانية تبدأ من هنا', 'العناية المثالية لسيارتك اليابانية تبدأ من هنا'),
  ('hero.description', 'خدمات صيانة متكاملة وقطع غيار عالية الجودة لسيارتك اليابانية، بأيدي خبراء متخصصين.', 'Complete maintenance services and high-quality spare parts for your Japanese car — in the hands of specialist experts.'),
  ('hero.cta_primary', 'احجز موعدك الآن', 'Book Your Appointment'),
  ('hero.cta_secondary', 'اكتشف خدماتنا', 'Explore Our Services'),
  ('hero.brands_label', 'متخصصون في', 'Specialists in'),
  ('about.eyebrow', 'ABOUT AL-EMAD', 'ABOUT AL-EMAD'),
  ('about.title', 'خبرة نعتز بها.. وثقة تستحقها سيارتك', 'Driven by Quality. Powered by Trust.'),
  ('about.subtitle', 'Driven by Quality. Powered by Trust.', ''),
  ('about.body', 'العماد مركز متخصص في صيانة السيارات اليابانية وتوفير قطع الغيار الأصلية وعالية الجودة. نجمع بين خبرة فنية متخصصة وأجهزة تشخيص حديثة لنقدّم لسيارتك العناية التي صُمّمت لها — بدقة، وشفافية، والتزام بالمواعيد.', 'AL-EMAD is a specialist centre for Japanese vehicle maintenance and genuine, high-quality spare parts. We combine focused technical expertise with modern diagnostic equipment to give your car the care it was engineered for — precise, transparent and on time.'),
  ('about.mission_title', 'رسالتنا', 'MISSION'),
  ('about.mission', 'تقديم خدمات صيانة وقطع غيار موثوقة للسيارات اليابانية بمعايير الوكيل وبأسعار عادلة وشفافة.', 'Reliable maintenance and parts for Japanese vehicles, to manufacturer standards and at fair, transparent prices.'),
  ('about.vision_title', 'رؤيتنا', 'VISION'),
  ('about.vision', 'أن نكون الوجهة الأولى لأصحاب السيارات اليابانية في المنطقة، والاسم الذي يثقون به لسياراتهم.', 'To be the region’s first choice for Japanese car owners — the name they trust with their vehicle.'),
  ('about.badge_number', '7', '7'),
  ('about.badge_text', 'علامات يابانية نتخصص في خدمتها', 'Japanese brands we specialise in'),
  ('about.image_main', 'https://images.pexels.com/photos/33814734/pexels-photo-33814734.jpeg?auto=compress&cs=tinysrgb&w=1400', 'https://images.pexels.com/photos/33814734/pexels-photo-33814734.jpeg?auto=compress&cs=tinysrgb&w=1400'),
  ('about.image_main_alt', 'ورشة العماد — خط الصيانة والرافعات', 'AL-EMAD workshop — service bays and lifts'),
  ('about.image_secondary', 'https://images.pexels.com/photos/3807517/pexels-photo-3807517.jpeg?auto=compress&cs=tinysrgb&w=900', 'https://images.pexels.com/photos/3807517/pexels-photo-3807517.jpeg?auto=compress&cs=tinysrgb&w=900'),
  ('about.image_secondary_alt', 'فني يفحص محرك سيارة', 'Technician inspecting an engine'),
  ('services.eyebrow', 'OUR SERVICES', 'OUR SERVICES'),
  ('services.title', 'كل ما تحتاجه سيارتك اليابانية تحت سقف واحد', 'Everything your Japanese car needs, under one roof'),
  ('services.description', 'من الفحص الدوري إلى الإصلاحات الدقيقة، نعمل وفق مواصفات الشركة المصنّعة وبأدوات تشخيص حديثة.', 'From scheduled servicing to precision repairs — to manufacturer specifications, with modern diagnostic tools.'),
  ('parts.eyebrow', 'GENUINE JAPANESE PARTS', 'GENUINE JAPANESE PARTS'),
  ('parts.title', 'قطع غيار يابانية أصلية وعالية الجودة', 'Genuine & high-quality Japanese spare parts'),
  ('parts.description', 'اختر علامة سيارتك لعرض القطع المتوافقة، واطلب عرض سعر مباشرةً من فريقنا.', 'Choose your car’s brand to see compatible parts, and request a quote directly from our team.'),
  ('parts.custom_request', 'اطلب قطعة غير موجودة', 'Request a part not listed'),
  ('parts.note', 'تُضاف المنتجات الفعلية وتصنيفاتها والعلامات المتوافقة من لوحة التحكم. لا تُعرض أسعار — كل قطعة بعرض سعر.', 'Products, categories and compatible brands are managed from the dashboard. No prices are shown — every part is quoted on request.'),
  ('why.eyebrow', 'WHY AL-EMAD', 'WHY AL-EMAD'),
  ('why.title', 'لماذا يختار أصحاب السيارات اليابانية العماد؟', 'Why do Japanese car owners choose AL-EMAD?'),
  ('why.description', 'لأن السيارة اليابانية تُبنى بدقة، وتستحق من يعرف تفاصيلها. هذا ما نلتزم به في كل زيارة.', 'Japanese cars are built with precision and deserve people who know every detail. That’s our commitment on every visit.'),
  ('why.image', 'https://images.pexels.com/photos/6870313/pexels-photo-6870313.jpeg?auto=compress&cs=tinysrgb&w=1400', 'https://images.pexels.com/photos/6870313/pexels-photo-6870313.jpeg?auto=compress&cs=tinysrgb&w=1400'),
  ('why.image_alt', 'فني يشخّص محرك سيارة داخل الورشة', 'Technician diagnosing an engine in the workshop'),
  ('why.1_title', 'خبرة متخصصة في السيارات اليابانية', 'Specialised Japanese Car Expertise'),
  ('why.1_text', 'تركيزنا على السيارات اليابانية يعني معرفة أعمق بأنظمتها وأعطالها الشائعة.', 'Our focus on Japanese cars means deeper knowledge of their systems and common faults.'),
  ('why.2_title', 'فنيون ذوو خبرة', 'Experienced Technicians'),
  ('why.2_text', 'فريق مدرّب يعمل وفق إجراءات واضحة ومعايير الشركة المصنّعة.', 'A trained team working to clear procedures and manufacturer standards.'),
  ('why.3_title', 'قطع غيار عالية الجودة', 'High-Quality Spare Parts'),
  ('why.3_text', 'قطع أصلية وبدائل معتمدة، مع توضيح نوع القطعة قبل التركيب.', 'Genuine parts and approved alternatives — always explained before fitting.'),
  ('why.4_title', 'أجهزة تشخيص حديثة', 'Modern Diagnostic Equipment'),
  ('why.4_text', 'نحدد العطل بدقة قبل الإصلاح، فتدفع فقط مقابل ما تحتاجه سيارتك.', 'We pinpoint the fault before repairing, so you only pay for what your car needs.'),
  ('why.5_title', 'خدمة عملاء احترافية', 'Professional Customer Service'),
  ('why.5_text', 'تواصل واضح، وتقدير مسبق للتكلفة، وإبلاغك بكل خطوة.', 'Clear communication, upfront estimates and updates at every step.'),
  ('why.6_title', 'التزام بالجودة', 'Commitment to Quality'),
  ('why.6_text', 'فحص نهائي لكل سيارة قبل التسليم، لأن سمعتنا تُبنى على كل تفصيلة.', 'A final check on every car before handover — our reputation is built on details.'),
  ('gallery.eyebrow', 'INSIDE THE WORKSHOP', 'INSIDE THE WORKSHOP'),
  ('gallery.title', 'جولة داخل ورشة العماد', 'Inside the AL-EMAD workshop'),
  ('testimonials.eyebrow', 'TESTIMONIALS', 'TESTIMONIALS'),
  ('testimonials.title', 'ماذا يقول عملاؤنا', 'What our customers say'),
  ('testimonials.description', 'التقييمات تُضاف وتُعدَّل من لوحة التحكم. المحتوى الحالي مؤقت حتى تصل تقييمات العملاء الحقيقية.', 'Reviews are added and edited from the dashboard. Current content is a placeholder until genuine customer reviews arrive.'),
  ('booking.eyebrow', 'BOOK AN APPOINTMENT', 'BOOK AN APPOINTMENT'),
  ('booking.title', 'احجز موعد صيانة سيارتك', 'Book your car’s service appointment'),
  ('booking.description', 'املأ النموذج وسيتواصل معك فريقنا لتأكيد الموعد، أو راسلنا مباشرة عبر واتساب.', 'Fill in the form and our team will contact you to confirm, or message us directly on WhatsApp.'),
  ('footer.description', 'مركز متخصص في صيانة السيارات اليابانية وقطع الغيار الأصلية — جودة نلتزم بها وثقة نحافظ عليها.', 'A specialist centre for Japanese car maintenance and genuine spare parts — quality we commit to, trust we keep.'),
  ('footer.copyright', 'العماد لخدمات السيارات. جميع الحقوق محفوظة.', 'AL-EMAD Automotive Services. All rights reserved.')
