insert into public.services (slug, sort_order, title_ar, title_en, summary_ar, summary_en, details_ar, details_en, image_url, image_alt_ar, image_alt_en) values
  ('engine-maintenance', 1, 'صيانة المحركات', 'Engine Maintenance', 'فحص وصيانة وإصلاح المحركات اليابانية وفق مواصفات الشركة المصنّعة.', 'Inspection, servicing and repair of Japanese engines to manufacturer specifications.', 'نشخّص أداء المحرك بدقة ونعالج مشكلات الأداء والتسريبات والأصوات غير الطبيعية، مع استبدال القطع المستهلكة بقطع أصلية أو معتمدة وتقديم تقرير واضح بما تم.', 'We accurately diagnose engine performance, fix power loss, leaks and unusual noises, and replace worn components with genuine or approved parts — with a clear report of the work done.', 'https://images.pexels.com/photos/8478259/pexels-photo-8478259.jpeg?auto=compress&cs=tinysrgb&w=1200', 'فني يعمل على محرك مكشوف', 'Technician working on an open engine'),
  ('transmission-services', 2, 'خدمات ناقل الحركة', 'Transmission Services', 'صيانة وإصلاح ناقل الحركة الأوتوماتيكي واليدوي و CVT، وتغيير الزيت والفلاتر.', 'Automatic, manual and CVT servicing and repair, fluid and filter changes.', 'فحص ناقل الحركة وقراءة أكواد الأعطال، وتغيير زيت ATF و CVT بالمواصفات الصحيحة، وإصلاح مشكلات التبديل والاهتزاز.', 'Transmission inspection and fault-code reading, ATF and CVT fluid changes to the correct spec, and repair of shifting and judder issues.', 'https://images.pexels.com/photos/20312398/pexels-photo-20312398.jpeg?auto=compress&cs=tinysrgb&w=1200', 'عصا ناقل الحركة داخل السيارة', 'Gear selector inside a car'),
  ('electrical-diagnostics', 3, 'تشخيص الأعطال الكهربائية', 'Electrical Diagnostics', 'تشخيص دقيق بأجهزة فحص حديثة لأنظمة الكهرباء والحساسات ووحدات التحكم.', 'Accurate fault-finding for electrics, sensors and control units with modern scan tools.', 'فحص شامل عبر منفذ OBD، وتتبع الأعطال الكهربائية، والحساسات، وأنظمة الشحن والبطارية ووحدات التحكم الإلكترونية.', 'Full OBD scanning, electrical fault tracing, sensors, charging and battery systems, and electronic control units.', 'https://images.pexels.com/photos/4116172/pexels-photo-4116172.jpeg?auto=compress&cs=tinysrgb&w=1200', 'جهاز تشخيص متصل بالسيارة', 'Diagnostic scanner connected to a car'),
  ('mechanical-repairs', 4, 'الإصلاحات الميكانيكية', 'Mechanical Repairs', 'إصلاح أنظمة التعليق والتوجيه والتبريد ومختلف الأعطال الميكانيكية.', 'Suspension, steering, cooling and all mechanical repairs.', 'إصلاح أنظمة التعليق والتوجيه والتبريد والعادم، واستبدال المساعدات والجلب والأذرع وفق مواصفات السيارة.', 'Repairs to suspension, steering, cooling and exhaust systems, including shocks, bushings and control arms to vehicle spec.', 'https://images.pexels.com/photos/8986105/pexels-photo-8986105.jpeg?auto=compress&cs=tinysrgb&w=1200', 'سيارة مرفوعة وفني أسفلها', 'Car on a lift, technician beneath'),
  ('oil-filter-replacement', 5, 'تغيير الزيت والفلاتر', 'Oil & Filter Replacement', 'زيوت وفلاتر بمواصفات معتمدة تحافظ على أداء المحرك وعمره.', 'Approved-spec oils and filters that protect engine performance and life.', 'تغيير زيت المحرك بالدرجة الموصى بها، واستبدال فلاتر الزيت والهواء والمكيّف، مع فحص سريع للسوائل.', 'Engine oil change with the recommended grade, oil, air and cabin filter replacement, plus a quick fluid check.', 'https://images.pexels.com/photos/36281957/pexels-photo-36281957.jpeg?auto=compress&cs=tinysrgb&w=1200', 'فحص مستوى زيت المحرك', 'Checking the engine oil level'),
  ('periodic-maintenance', 6, 'الصيانة الدورية', 'Periodic Maintenance', 'برامج صيانة حسب عدد الكيلومترات وتوصيات الوكيل، مع تقرير فحص شامل.', 'Mileage-based service plans following dealer recommendations, with a full report.', 'صيانة دورية حسب جدول الشركة المصنّعة (10,000 / 20,000 / 40,000 كم…) مع قائمة فحص شاملة وتقرير مكتوب.', 'Scheduled servicing per the manufacturer''s interval plan, with a comprehensive checklist and written report.', 'https://images.pexels.com/photos/7736042/pexels-photo-7736042.jpeg?auto=compress&cs=tinysrgb&w=1200', 'فني يراجع قائمة الفحص بجانب السيارة', 'Technician with an inspection checklist'),
  ('brake-system-services', 7, 'خدمات نظام الفرامل', 'Brake System Services', 'فحص واستبدال الفحمات والأقراص وصيانة نظام ABS لقيادة آمنة.', 'Pads, discs and ABS servicing for safe, confident braking.', 'فحص سماكة الفحمات والأقراص، وتغيير زيت الفرامل، وتشخيص أعطال ABS لضمان توقف آمن.', 'Pad and disc wear checks, brake fluid replacement and ABS diagnostics for safe stopping.', 'https://images.pexels.com/photos/34277923/pexels-photo-34277923.jpeg?auto=compress&cs=tinysrgb&w=1200', 'قرص وفحمات فرامل عن قرب', 'Brake disc and pads close-up'),
  ('japanese-car-spare-parts', 8, 'قطع غيار السيارات اليابانية', 'Japanese Car Spare Parts', 'قطع أصلية وبدائل عالية الجودة لمختلف الطرازات اليابانية.', 'Genuine and high-quality parts for a wide range of Japanese models.', 'نوفّر قطعًا أصلية وبدائل معتمدة لتويوتا ولكزس ونيسان وهوندا وميتسوبيشي ومازدا وسوبارو، مع إمكانية الطلب المسبق.', 'Genuine and approved parts for Toyota, Lexus, Nissan, Honda, Mitsubishi, Mazda and Subaru, with pre-order available.', 'https://images.pexels.com/photos/19499386/pexels-photo-19499386.jpeg?auto=compress&cs=tinysrgb&w=1200', 'قطع غيار سيارات', 'Automotive spare parts')
  insert into public.part_categories (name_ar, name_en, sort_order) values ('الفلاتر', 'Filters', 1) returning id into cat;
  insert into public.parts (category_id, name_ar, name_en, description_ar, description_en, image_url, image_alt_ar, image_alt_en, brands, sort_order) values (cat, 'فلاتر الزيت والهواء والمكيّف', 'Oil, Air & Cabin Filters', 'فلاتر أصلية وبمواصفات المصنّع لحماية المحرك وجودة هواء المقصورة.', 'Genuine and OEM-spec filters to protect the engine and cabin air quality.', 'https://images.pexels.com/photos/4489765/pexels-photo-4489765.jpeg?auto=compress&cs=tinysrgb&w=1000', 'محرك سيارة أثناء الصيانة', 'Engine bay during servicing', array['Toyota','Lexus','Nissan','Honda','Mitsubishi','Mazda','Subaru']::text[], 1);
  insert into public.part_categories (name_ar, name_en, sort_order) values ('الفرامل', 'Brakes', 2) returning id into cat;
  insert into public.parts (category_id, name_ar, name_en, description_ar, description_en, image_url, image_alt_ar, image_alt_en, brands, sort_order) values (cat, 'فحمات وأقراص الفرامل', 'Brake Pads & Discs', 'قطع فرامل أصلية ومعتمدة لأداء كبح ثابت وآمن.', 'Genuine and approved brake parts for consistent, safe braking.', 'https://images.pexels.com/photos/20408753/pexels-photo-20408753.jpeg?auto=compress&cs=tinysrgb&w=1000', 'عجلة وقرص فرامل', 'Wheel and brake disc', array['Toyota','Lexus','Nissan','Honda','Mazda']::text[], 2);
  insert into public.part_categories (name_ar, name_en, sort_order) values ('المحرك', 'Engine', 3) returning id into cat;
  insert into public.parts (category_id, name_ar, name_en, description_ar, description_en, image_url, image_alt_ar, image_alt_en, brands, sort_order) values (cat, 'قطع المحرك وسيور التوقيت', 'Engine Parts & Timing Belts', 'سيور، شمعات، حشوات ومضخات لمحركات السيارات اليابانية.', 'Belts, spark plugs, gaskets and pumps for Japanese engines.', 'https://images.pexels.com/photos/19499386/pexels-photo-19499386.jpeg?auto=compress&cs=tinysrgb&w=1000', 'قطع محرك', 'Engine components', array['Toyota','Nissan','Mitsubishi','Subaru']::text[], 3);
  insert into public.part_categories (name_ar, name_en, sort_order) values ('ناقل الحركة', 'Transmission', 4) returning id into cat;
  insert into public.parts (category_id, name_ar, name_en, description_ar, description_en, image_url, image_alt_ar, image_alt_en, brands, sort_order) values (cat, 'قطع وزيوت ناقل الحركة', 'Transmission Parts & Fluids', 'زيوت ATF و CVT وفلاتر وحشوات بمواصفات الوكيل.', 'ATF and CVT fluids, filters and gaskets to dealer spec.', 'https://images.pexels.com/photos/8986137/pexels-photo-8986137.jpeg?auto=compress&cs=tinysrgb&w=1000', 'أسفل السيارة على الرافعة', 'Vehicle underside on a lift', array['Toyota','Lexus','Nissan','Honda']::text[], 4);
  insert into public.part_categories (name_ar, name_en, sort_order) values ('الكهرباء', 'Electrical', 5) returning id into cat;
  insert into public.parts (category_id, name_ar, name_en, description_ar, description_en, image_url, image_alt_ar, image_alt_en, brands, sort_order) values (cat, 'حساسات وبطاريات وقطع كهربائية', 'Sensors, Batteries & Electrical', 'حساسات أكسجين وABS، بطاريات، مولدات وقطع إشعال.', 'Oxygen and ABS sensors, batteries, alternators and ignition parts.', 'https://images.pexels.com/photos/37177070/pexels-photo-37177070.jpeg?auto=compress&cs=tinysrgb&w=1000', 'بطارية سيارة داخل حجرة المحرك', 'Car battery in the engine bay', array['Toyota','Lexus','Nissan','Honda','Mitsubishi','Mazda','Subaru']::text[], 5);
  insert into public.part_categories (name_ar, name_en, sort_order) values ('التعليق', 'Suspension', 6) returning id into cat;
  insert into public.parts (category_id, name_ar, name_en, description_ar, description_en, image_url, image_alt_ar, image_alt_en, brands, sort_order) values (cat, 'قطع التعليق والتوجيه', 'Suspension & Steering Parts', 'مساعدات، جلب، أذرع ومقصات لثبات وراحة القيادة.', 'Shocks, bushings, arms and links for stable, comfortable driving.', 'https://images.pexels.com/photos/8986138/pexels-photo-8986138.jpeg?auto=compress&cs=tinysrgb&w=1000', 'سيارة دفع رباعي على رافعة الصيانة', 'SUV on a service lift', array['Toyota','Nissan','Mitsubishi','Mazda','Subaru']::text[], 6);
